mapper.update:
UPDATE `inspection`.`inspection_task_issue_list` a
SET
    a.DEPARTMENT_HEAD = #{params.DEPARTMENT_HEAD},
    a.AFTER_HEAD = #{params.AFTER_HEAD},
    a.PAPER_ATTACHMENT = #{params.PAPER_ATTACHMENT},
    a.PRINT_ATTACHMENT = #{params.PRINT_ATTACHMENT},
    a.MODIFY_DATE         = #{params.MODIFY_DATE}
WHERE 1=1

    AND a.`ISSUE_ID` = #{params.ISSUE_ID}


    AND a.`TASK_ID` = #{params.TASK_ID}
